actions.script:
def orgId = scope.organizationPartyId
if (!orgId || orgId == '_NA_') {
    ec.message.addError("No active shop selected. Open the POS for your shop first, then set the discount rules.")
    return
}
def savePref = { k, v ->
    def existing = ec.entity.find("moqui.security.UserPreference")
        .condition("userId", orgId).condition("preferenceKey", k).one()
    if (existing) { existing.preferenceValue = (v != null ? v.toString() : ''); existing.update() }
    else { ec.entity.makeValue("moqui.security.UserPreference")
        .setAll([userId: orgId, preferenceKey: k, preferenceValue: (v != null ? v.toString() : '')]).create() }
}

// Discount limit % — clamp 0..100; blank means "no limit gate"
def limStr = (context.discountLimitPct != null ? context.discountLimitPct.toString().trim() : '')
if (limStr != '') {
    BigDecimal lim
    try { lim = new BigDecimal(limStr) } catch (Exception e) {
        ec.message.addError("Discount limit must be a number (e.g. 10)."); return
    }
    if (lim < 0) lim = BigDecimal.ZERO
    if (lim > 100) lim = new BigDecimal("100")
    savePref('POS_DISC_LIMIT', lim.stripTrailingZeros().toPlainString())
} else {
    savePref('POS_DISC_LIMIT', '')
}

// Round-off step — from a fixed dropdown, so it is already one of 0/1/5/10
def stepStr = (context.roundOffStep != null ? context.roundOffStep.toString().trim() : '')
savePref('POS_DISC_ROUNDSTEP', stepStr == '' ? '0' : stepStr)

// Manager PIN — write-only. Blank = leave unchanged. Clear checkbox = remove it.
def clearPin = (context.clearPin == 'Y' || context.clearPin == true)
def pinStr = (context.managerPin != null ? context.managerPin.toString().trim() : '')
if (clearPin) {
    savePref('POS_DISC_PIN', '')
    ec.message.addMessage("Discount rules saved. Manager PIN removed.")
} else if (pinStr != '') {
    if (!(pinStr ==~ /\d{4,6}/)) {
        ec.message.addError("Manager PIN must be 4 to 6 digits."); return
    }
    savePref('POS_DISC_PIN', pinStr)
    ec.message.addMessage("Discount rules saved. Manager PIN updated.")
} else {
    ec.message.addMessage("Discount rules saved.")
}

BigDecimal percent
try { percent = new BigDecimal((discountPercent ?: '').toString().trim()) }
catch (NumberFormatException ignored) { ec.message.addError('Enter a discount from 0 to 100%.'); return }
if (percent < 0 || percent > 100 || percent.stripTrailingZeros().scale() > 2) {
    ec.message.addError('Enter a discount from 0 to 100% with up to two decimal places.'); return
}

def orgId = scope.organizationPartyId
// Saving a KOT quote takes the same mode lock before reading the discount.
def mode = salesModeId ? ec.entity.find('zenith.erp.pos.PosSalesMode')
    .condition('salesModeId',salesModeId).condition('organizationPartyId',orgId)
    .condition('isActive','Y').condition('priceSource','PpsDiscountMrp').forUpdate(true).one() : null
if (!mode) { ec.message.addError('Choose an active discount mode owned by your organization.'); return }

// Unpaid KOTs carry a saved quote. Changing its pricing would block checkout.
def snapshots = ec.entity.find('zenith.erp.pos.KitchenOrderTicket').condition('organizationPartyId',orgId)
    .condition('transactionId',null).condition('statusId','in',['KotDraft','KotNew','KotPreparing','KotReady','KotServed'])
    .selectField('orderReceiptJson').list()
def pendingKot = snapshots.any { ticket ->
    if (!ticket.orderReceiptJson?.contains(salesModeId)) return false
    try { return new groovy.json.JsonSlurper().parseText(ticket.orderReceiptJson)?.bill?.salesModeId == salesModeId }
    catch (groovy.json.JsonException ignored) { return false }
}
if (pendingKot) { ec.message.addError('Settle or cancel unpaid KOTs in this mode before changing it.'); return }
ec.entity.makeValue('zenith.erp.base.CompanySettings').setAll([
    organizationPartyId:orgId, settingKey:'KOT_MODE_DISCOUNT_'+salesModeId,
    settingValue:percent.stripTrailingZeros().toPlainString()]).createOrUpdate()
ec.message.addMessage('KOT discount saved.')

def orgId = posOrganizationPartyId
if (kitchenModuleId == 'kot') {
    kotDiscountModes = orgId ? ec.service.sync().name('zenith.pos.PosModeServices.get#OrganizationModes')
        .parameter('organizationPartyId',orgId).call().modes?.findAll {
            it.organizationPartyId == orgId && it.priceSource == 'PpsDiscountMrp'
        } : []
    def keys = (kotDiscountModes ?: []).collect { 'KOT_MODE_DISCOUNT_'+it.salesModeId }
    kotDiscounts = keys ? ec.entity.find('zenith.erp.base.CompanySettings')
        .condition('organizationPartyId',orgId).condition('settingKey','in',keys).list()
        .collectEntries { [(it.settingKey):(it.settingValue as BigDecimal)] } : [:]
    kotCanManageDiscount = modCanWrite && ['ADMIN','ZENITH_ADMIN','ZENITH_STORE_MGR'].any { ec.user.isInGroup(it) }
    return
}
hasOrg = (orgId && orgId != '_NA_')
def rd = { k -> hasOrg ? ec.entity.find("moqui.security.UserPreference")
    .condition("userId", orgId).condition("preferenceKey", k).one()?.preferenceValue : null }
def curLimit = rd('POS_DISC_LIMIT')
def curStep = rd('POS_DISC_ROUNDSTEP')
def curPin = rd('POS_DISC_PIN')
// pre-fill the form from saved values (the PIN is NEVER pre-filled — write-only)
discountLimitPct = (curLimit != null && curLimit.toString().trim() != '') ? curLimit.toString().trim() : ''
roundOffStep = (curStep != null && curStep.toString().trim() != '') ? curStep.toString().trim() : '0'
// Current-rules chips (the PIN value is never shown — only Set / Not set)
limitChip = (discountLimitPct != '') ? (discountLimitPct + '%') : 'No limit'
stepDisplay = (roundOffStep == '0' || roundOffStep == '') ? 'Off' : ('₹' + roundOffStep)
roundChip = (roundOffStep == '0' || roundOffStep == '') ? 'Off' : ('Nearest ₹' + roundOffStep)
pinDisplay = (curPin != null && curPin.toString().trim() != '') ? 'Set' : 'Not set'
pinChipClass = (pinDisplay == 'Set') ? 'success' : 'warning'
